    n = len(matrix)
    A = [row[:] for row in matrix]
    rank = 0

    for j in range(n):
        i_max = max(range(rank, n), key=lambda i: abs(A[i][j]))
        if A[i_max][j] == 0:
            continue
        A[rank], A[i_max] = A[i_max], A[rank]

        pivot = A[rank][j]
        for i in range(n):
            if i != rank:
                factor = Fraction(A[i][j], pivot)
                for k in range(j, n):
                    A[i][k] -= factor * A[rank][k]
        rank += 1

    return rank

